const prior=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/closure-fixes-verification.json','utf8'));
const scope=[];for(let i=0;i<prior.gates[2].command.length;i++)if(prior.gates[2].command[i]==='--scope')scope.push(prior.gates[2].command[i+1]);
const inventory=gates.loadInventory('/tmp/phase06/review-doc-inventory.json',{});
