if(global.gc)global.gc();
const registry=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/working-identity-registry.json','utf8'));
const vocabulary=JSON.parse(fs.readFileSync(root+'/'+plan+'/claim-and-disposition-vocabulary.json','utf8'));
const shards=[...gates.loadDecisionShards(root+'/'+plan+'/pilot/decisions'),...gates.loadDecisionShards(root+'/'+plan+'/ledger/decisions')];
const merged=gates.applyDecisions(inventory,shards,{vocabulary,registry,repoRoot:root,unitsOf:gates.buildConservationUnitLookup(root,inventory.commit),targetAnchorsOf:gates.buildTargetAnchorLookup(root,inventory.commit),targetUnitDigestOf:gates.buildTargetUnitDigestLookup(root,inventory.commit)});
const reverse=gates.unreferencedCandidateRows(merged.inventory,shards,{scope,repoRoot:root});
const list=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/candidate-unverified-agent-coordination.json','utf8')).rows;
const key=r=>[r.path,r.anchor,r.unitDigest].join('\0');
const listed=new Set(list.map(key)),actual=new Set(reverse.map(key));
const missing=list.filter(r=>!actual.has(key(r))),extra=reverse.filter(r=>!listed.has(key(r)));
const holds=merged.inventory.claimLedger.filter(r=>gates.pathInScope(r.sourcePath,scope)&&r.reviewStatus!=='reviewed').map(r=>r.claimId).sort();
const expectedHolds=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/closure-fixes-applied.json','utf8')).holdsUnchanged.slice().sort();
const result={inventoryCommit:inventory.commit,holds,holdsEqual:JSON.stringify(holds)===JSON.stringify(expectedHolds),listedUnits:list.length,actualReverseUnits:reverse.length,listedMissing:missing,additionalReverseUnits:extra,exactEquality:missing.length===0&&extra.length===0,identityEqualityOfListedUnits:list.every(r=>reverse.some(u=>u.claimId===r.claimId&&key(u)===key(r))),applicationFindingTypes:[...new Set(merged.findings.map(f=>f.type))]};
result.actualReverseIdentityRows=reverse;result.matchingListedIdentityRows=list.filter(r=>reverse.some(u=>u.claimId===r.claimId&&key(u)===key(r)));
const exceptionFile=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/identical-unit-exceptions.json','utf8'));const grouped=new Map();for(const row of merged.inventory.claimLedger){if(!gates.pathInScope(row.sourcePath,scope)||!row.sourceUnitDigest||!row.targetOwner)continue;const group=grouped.get(row.sourceUnitDigest)||{digest:row.sourceUnitDigest,ids:[],owners:new Set()};group.ids.push(row.claimId);group.owners.add(row.targetOwner);grouped.set(row.sourceUnitDigest,group);}const actualGroups=[...grouped.values()].filter(g=>g.owners.size>1).map(g=>({digest:g.digest,ids:g.ids.sort()})).sort((a,b)=>a.digest.localeCompare(b.digest));const expectedGroups=exceptionFile.groups.map(g=>({digest:g.digest,ids:g.sourceUnits.map(u=>u.claimId).sort()})).sort((a,b)=>a.digest.localeCompare(b.digest));result.exceptionGroups=actualGroups.length;result.exceptionDigestEquality=JSON.stringify(actualGroups.map(g=>g.digest))===JSON.stringify(expectedGroups.map(g=>g.digest));result.exceptionIdEquality=JSON.stringify(actualGroups)===JSON.stringify(expectedGroups);result.exceptionActual=actualGroups;result.exceptionExpected=expectedGroups;fs.writeFileSync('/tmp/phase06/agent-coordination-closure-equality.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({holds:holds.length,holdsEqual:result.holdsEqual,listed:list.length,reverse:reverse.length,missing:missing.length,additional:extra.length,listedIdentityEquality:result.identityEqualityOfListedUnits,exactEquality:result.exactEquality}));
